public static boolean isTriple(Node<Integer> L) {
    int len = 0;
    Node<Integer> p = L;
    while (p != null) {
        len++;
        p = p.getNext();
    }
    if (len == 0 || len % 3 != 0) {
        return false;
    }
    int third = len / 3;
    Node<Integer> second = L;
    for (int i = 0; i < third; i++) {
        second = second.getNext();
    }
    Node<Integer> last = second;
    for (int i = 0; i < third; i++) {
        last = last.getNext();
    }
    Node<Integer> first = L;
    for (int i = 0; i < third; i++) {
        int a = first.getValue();
        int b = second.getValue();
        int c = last.getValue();
        if (a != b || a != c) {
            return false;
        }
        first = first.getNext();
        second = second.getNext();
        last = last.getNext();
    }
    return true;
}

